       {"ID":"35832680","IP":"171.128.225.96","TRACKING_METHOD":"AGENT",
        "OS":"Red Hat Enterprise Linux 9.8",
        "DNS":"ah-1047132-001.sdi.corp.bankofamerica.com",
        "SERIAL_NUMBER":"VMware-42 1a 9c 3f 7d 2e 61 b8-55 04 e2 91 6a 27 c3 08"}
