helpers.script:
var CIIdentify = Class.create();
CIIdentify.prototype = {

    _PROP_IGNORE_NULL_VALUES: true,
    _IGNORE_CLASS_LIST: ["sn_sec_cmn_unmatched_ci", "cmdb_ci_unclassed_hardware", "cmdb_ci_incomplete_ip"],
    _PRODUCT_MODEL: false,

    initialize: function() {
        this.util = new sn_sec_cmn.SecCommonUtil();
        this.autoPromoteFields = global.SecProperty.getProperty("sn_sec_cmn.autoPromoteFields", "");
        if (this.autoPromoteFields) {
            this.autoPromoteFieldsJson = JSON.parse(this.autoPromoteFields);
        } else {
            this.autoPromoteFieldsJson = {
                "dscy_switchport": "cmdb_ci",
                "cmdb_ci_network_adapter": "cmdb_ci",
                "cmdb_ci_nic": "cmdb_ci",
                "cmdb_ci_ip_address": [
                    "owned_by_cmdb_ci",
                    "nic"
                ],
                "cmdb_ci_vmware_nic": "cmdb_ci"
            };
        }
        this.filterDecommissionCi = global.SecProperty.getProperty("sn_sec_cmn.filterOutDecommissionedCI", "true");
        this.ignoreClassArr = this._getIgnoreClass();
        this.ignoreClass = this.ignoreClassArr.join(",");
    },

    getCILookupRules: function(source) {
        if (sn_sec_cmn.ciLookupRuleCache && sn_sec_cmn.ciLookupRuleCache[source] && sn_sec_cmn.ciLookupRuleCache[source].list)
            return sn_sec_cmn.ciLookupRuleCache[source];
        else {
            var listRuleIds = [];
            var rules = {};
            var rule = new GlideRecord("sn_sec_cmn_ci_lookup_rule");
            rule.addQuery("source", source);
            rule.addActiveQuery();
            rule.orderBy("order");
            rule.query();
            while (rule.next()) {
                listRuleIds.push(rule.getUniqueValue());
                rules[rule.getUniqueValue()] = this._makeObjectFromRule(rule);
            }
            var cacheObj = {
                list: listRuleIds,
                rules: rules
            };

            if (!sn_sec_cmn.ciLookupRuleCache)
                sn_sec_cmn.ciLookupRuleCache = {};
            sn_sec_cmn.ciLookupRuleCache[source] = cacheObj;
            return cacheObj;
        }
    },

    _makeObjectFromRule: function(grRule) {
        var gr = new GlideRecord(grRule.getTableName());
        gr.get(grRule.getUniqueValue());
        return gr;
    },

    identify: function(source /*sys_id*/ , srcValues /*json*/ , isReqLookupRule /*bool*/ , hostRecord /*asset wrapped by glide record*/ ) {
        var ciLookupRules = this.getCILookupRules(source);
        if ((!ciLookupRules) || (!ciLookupRules.list) || (!ciLookupRules.rules))
            return;

        var returnCIAndRule = {};
        for (var i = 0; i < ciLookupRules.list.length; i++) {
            var rule = ciLookupRules.rules[ciLookupRules.list[i]];
            var values = Object.keys(srcValues);
            if (values.indexOf(rule.getValue("source_field")) != -1) {

                if (rule.getValue("lookup_target") == "product_model")
                    this._PRODUCT_MODEL = true;
                else
                    this._PRODUCT_MODEL = false;

                if (hostRecord && rule.condition && !this.util.checkRecord(hostRecord, rule.condition))
                    continue;

                var identifyFunction = null;
                if (rule.getValue("method") == "field_matching")
                    identifyFunction = this._identifyViaFieldMatching.bind(this);
                else if (rule.getValue("method") == "script" && rule.getValue("type") == "custom")
                    identifyFunction = this._identifyViaScript.bind(this);
                else
                    identifyFunction = this._identifyViaReferenceScript.bind(this);

                if (!identifyFunction)
                    gs.error("missing identify function for identify rule method '" + rule.getValue("method") + "'");
                else {
                    if (srcValues.hasOwnProperty(rule.source_field) &&
                        this._PROP_IGNORE_NULL_VALUES && srcValues[rule.source_field]) {
                        if (this._PRODUCT_MODEL)
                            returnCIAndRule.product_model = identifyFunction(rule, srcValues);
                        else
                            returnCIAndRule.ci = identifyFunction(rule, srcValues);
                    }
                }

                if (isReqLookupRule && (returnCIAndRule.ci || returnCIAndRule.product_model)) {
                    returnCIAndRule.lookupRule = rule.getUniqueValue();
                    return returnCIAndRule; // lookup rule required
                }
                if (returnCIAndRule.ci)
                    return returnCIAndRule.ci; // lookup rule not required
                if (returnCIAndRule.product_model)
                    return returnCIAndRule.product_model; // lookup rule not required
            }
        }
        return null; // not matched
    },

    getLookupScriptByMethod: function(method) {
        return this._getLookupScriptByMethod(method);
    },

    _getLookupScriptByMethod: function(method) {
        var gr = new GlideRecord("sn_sec_cmn_ci_lookup_type_script");
        gr.addQuery("value", method);
        gr.query();

        if (gr.next())
            return gr.getUniqueValue();
        else
            return "";
    },

    getLookupTypeScriptNames: function() {
        return this._getLookupTypeScriptNames();
    },

    _getLookupTypeScriptNames: function() {
        var list = [];

        var gr = new GlideRecord("sn_sec_cmn_ci_lookup_type_script");
        gr.query();

        while (gr.next())
            list.push({
                type: gr.type + '',
                value: gr.value + ''
            });

        return new global.JSON().encode(list);
    },

    _autoPromoteCIID: function(ciId) {
        var grCI = new GlideRecord("cmdb_ci");
        if (!grCI.get(ciId))
            return "";
        return this._autoPromoteCI(ciId, grCI);
    },

    _autoPromoteCIRecord: function(grCI) {
        if (!grCI)
            return "";
        if (!grCI.isValidRecord())
            return "";
        return this._autoPromoteCI(grCI.getUniqueValue(), grCI);
    },

    _autoPromoteCI: function(ciId, grCI) {
        var idList = ciId; // Store a list of IDs so we don't duplicate
        var currentId = ciId;
        var currentRecord = grCI;
        var previousRecord = "";
        // Limit autopromote to 10 levels
        for (var i = 0; i < 10; ++i) {
            // Validate CI record
            if (!currentRecord)
                return previousRecord;
            if (!currentRecord.isValidRecord())
                return previousRecord;

            // check for ignoreClass
            if (this._checkCIIgnored(currentRecord, this.ignoreClassArr))
                return "";

            // Check if autopromote needed
            var autoPromoteField = this._getAutoPromoteField(currentRecord);
            if (!autoPromoteField)
                return currentRecord;

            // Autopromote
            previousRecord = currentRecord;
            if (currentRecord.isValidField(autoPromoteField))
                currentId = currentRecord.getValue(autoPromoteField);
            else {
                var grCast = new GlideRecord(currentRecord.sys_class_name);
                if (!grCast.get(currentRecord.getUniqueValue()))
                    return previousRecord;
                if (!grCast.isValidField(autoPromoteField))
                    return previousRecord;
                currentId = grCast.getValue(autoPromoteField);
            }
            // Check for looping pointers, add current pointer to list
            if (idList.includes(currentId))
                return previousRecord;
            idList += "," + currentId;

            // Get new record
            currentRecord = new GlideRecord("cmdb_ci");
            currentRecord.get(currentId);
        }
    },

    _getAutoPromoteField: function(currentRecord) {
        var ciClassName = currentRecord.sys_class_name + "";
        var fieldMap = this.autoPromoteFieldsJson;
        if (ciClassName in fieldMap) {
            if (Array.isArray(fieldMap[ciClassName])) {
                for (var items = 0; items < fieldMap[ciClassName].length; items++) {
                    if (currentRecord.isValidField(fieldMap[ciClassName][items]))
                        return fieldMap[ciClassName][items];
                    else {
                        var grCast = new GlideRecord(ciClassName);
                        if (!grCast.get(currentRecord.getUniqueValue()))
                            return "";
                        if (grCast.isValidField(fieldMap[ciClassName][items]) && !gs.nil(grCast.getValue(fieldMap[ciClassName][items])))
                            return fieldMap[ciClassName][items];
                    }
                }
            } else
                return fieldMap[ciClassName];
        }

        return "";
    },

    _identifyViaFieldMatching: function(rule /*gr*/ , srcValues /*json*/ ) {
        this.returnObj = {
            'ciIds': []
        };
        //Use the appropriate target table and target field based on product model or ci
        var target_table;
        var target_field;
        if (!this._PRODUCT_MODEL) {
            target_table = rule.target_table;
            target_field = rule.target_field;
        } else {
            target_table = rule.target_table_product_model;
            target_field = rule.target_field_product_model;
        }
        var srcValue = srcValues[rule.source_field];
        var gr = new GlideRecord(target_table);
        // Ignore specific class names
        for (var i = 0; i < this.ignoreClassArr.length; i++) {
            var ignoredTable = this.ignoreClassArr[i];
            gr.addQuery("sys_class_name", "!=", ignoredTable);
        }
        gr.setLimit(10); // limit to 10
        gr.query(target_field, srcValue);
        gr = this._queryMatch(gr, rule, srcValues);
        if (gs.nil(gr))
            return null;
        if (this._PRODUCT_MODEL)
            return gr.getUniqueValue();
        return this._filterCI(gr.getUniqueValue(), this.returnObj.ciIds);
    },

    _identifyViaScript: function(rule /*gr*/ , srcValues /*json*/ ) {
        var srcValue = srcValues[rule.source_field];
        var returnObj = {
            'ciIds': []
        };
        var evaluator = new GlideScopedEvaluator();
        evaluator.putVariable('rule', rule);
        evaluator.putVariable('sourceValue', srcValue);
        evaluator.putVariable('sourcePayload', srcValues);
        evaluator.putVariable('_queryMatch', this._queryMatch);
        evaluator.putVariable('_logDupWhileIdentifying', this._logDupWhileIdentifying);
        evaluator.putVariable('_ignoreClass', this.ignoreClass);
        evaluator.putVariable('_cacheCi', this._cacheCi);
        evaluator.putVariable('returnObj', returnObj);
        if (this._PRODUCT_MODEL)
            return evaluator.evaluateScript(rule, 'script', null);
        return this._filterCI(evaluator.evaluateScript(rule, 'script', null), returnObj.ciIds);
    },

    _identifyViaReferenceScript: function(rule /*gr*/ , srcValues /*json*/ ) {
        var srcValue = srcValues[rule.source_field];
        var lookupScript = new GlideRecord("sn_sec_cmn_ci_lookup_type_script");
        if (lookupScript.get(rule.lookup_script)) {
            var returnObj = {
                'ciIds': []
            };
            var evaluator = new GlideScopedEvaluator();
            evaluator.putVariable('rule', rule);
            evaluator.putVariable('sourceValue', srcValue);
            evaluator.putVariable('sourcePayload', srcValues);
            evaluator.putVariable('_queryMatch', this._queryMatch);
            evaluator.putVariable('_logDupWhileIdentifying', this._logDupWhileIdentifying);
            evaluator.putVariable('_ignoreClass', this.ignoreClass);
            evaluator.putVariable('_cacheCi', this._cacheCi);
            evaluator.putVariable('returnObj', returnObj);
            if (this._PRODUCT_MODEL)
                return evaluator.evaluateScript(rule, 'script', null);
            return this._filterCI(evaluator.evaluateScript(lookupScript, 'script', null), returnObj.ciIds);
        }

        return null;
    },

    _queryMatch: function(gr, rule, srcValues) {
        if (!gr.hasNext()) // no match
            return null;

        var cmdbGr = this._cacheCi(gr);
        // duplicate matches
        if (!gs.nil(cmdbGr) && this.returnObj.ciIds.length > 1)
            this._logDupWhileIdentifying(cmdbGr, rule, srcValues);
        return cmdbGr;
    },

    _logDupWhileIdentifying: function(chosenCI, rule, srcValues) {
        gs.info("Found duplicate CI while identifying rule '" + rule.name + "' " + rule.getUniqueValue() + " source values=" + JSON.stringify(srcValues) + " deciding to return this CI '" + chosenCI.getUniqueValue() + "'");
    },

    _cacheCi: function(gr) {
        var limit = 10; // limit number of records
        var firstCiSysId = null;
        var table = null;
        this.returnObj.ciIds = [];
        while (gr.next() && limit > 0) {
            if (gs.nil(firstCiSysId)) {
                firstCiSysId = gr.getUniqueValue();
                table = gr.getTableName();
            }
            this.returnObj.ciIds.push(gr.getUniqueValue());
            limit--;
        }
        if (gs.nil(firstCiSysId) || gs.nil(table))
            return null;
        // get first record
        var firstCi = new GlideRecord(table);
        firstCi.get(firstCiSysId);
        return firstCi;
    },

    _filterCI: function(mainCi, ciList) {
        if (gs.nil(mainCi))
            return null;
        var ciObj = {};
        // making sure whatever is returned is part of list
        if (ciList.indexOf(mainCi) == -1)
            ciList.push(mainCi);
        var filterList = [];
        // list to store records which are not unmatched or unclassed
        var priorityList = [];
        for (var i = 0; i < ciList.length; i++) {
            var ci = this._autoPromoteCIID(ciList[i]);
            // check if duplicate ci
            if (!gs.nil(ci) && ci.isValidField("duplicate_of") && !gs.nil(ci.duplicate_of)) {
                var dup = ci.getValue("duplicate_of");
                ci = new GlideRecord("cmdb_ci");
                ci.get(dup);
                //check for ignore
                if (this._checkCIIgnored(ci, this.ignoreClassArr))
                    ci = null;
            }
            // check ci not retired
            if (!gs.nil(ci) && !this._isCIDecommissioned(ci, this.filterDecommissionCi) && filterList.indexOf(ci.getUniqueValue()) == -1) {
                filterList.push(ci.getUniqueValue());
                if (ci.sys_class_name != null && ci.sys_class_name != '' && this._IGNORE_CLASS_LIST.indexOf(ci.getValue("sys_class_name")) == -1) {
                    priorityList.push(ci.getUniqueValue());
                }
            }
        }
        if (filterList.length === 0)
            return null;
        if (priorityList.length === 0)
            priorityList = filterList;
        var cmdb = new GlideRecord("cmdb_ci");
        cmdb.addQuery("sys_id", "IN", priorityList);
        cmdb.orderByDesc("sys_created_on");
        cmdb.query();
        while (cmdb.next()) {
            if (!this._isOrphan(cmdb)) {
                ciObj.mainCi = cmdb.getUniqueValue();
                // remove ci from other matched ci list
                filterList.splice(filterList.indexOf(cmdb.getUniqueValue()), 1);
                ciObj.ciIds = filterList;
                return ciObj;
            }
        }
        return null;
    },

    _isOrphan: function(gr) {
        if (gr.sys_class_name == null || gr.sys_class_name == '') return false;
        var childClass = new GlideRecord(gr.sys_class_name);
        if (!childClass.isValid()) return true;
        childClass.get(gr.sys_id);
        return !childClass.isValidRecord();
    },

    _isCIDecommissioned: function(gr, filterDecommissionCi) {
        var install_status = false;
        var life_cycle_stage_status = false;
        var operational_status = false;
        // check for property
        if (filterDecommissionCi == "true") {
            if (gr.isValidField("install_status"))
                install_status = gr.install_status == 7;
            if (gr.isValidField("life_cycle_stage_status"))
                life_cycle_stage_status = gr.life_cycle_stage_status == "Retired";
            if (gr.isValidField("operational_status"))
                operational_status = gr.operational_status == 6;

        }
        return install_status || life_cycle_stage_status || operational_status;
    },

    _getIgnoreClass: function() {
        var ignoreClass = global.SecProperty.getProperty("sn_sec_cmn.ignoreCIClass", "");
        if (!gs.nil(ignoreClass))
            ignoreClass = ignoreClass.split(",").map(function(item) {
                return item.trim();
            });
        else
            ignoreClass = [];
        return ignoreClass;
    },

    _checkCIIgnored: function(gr, ignoreClass) {
        if (ignoreClass.length > 0 && ignoreClass.indexOf(gr.sys_class_name + "") != -1)
            return true;
        return false;
    },

    type: 'CIIdentify'
};
